# Try identity mapping with cleaner rectangular segments
test_scatters = [
    (6, 21, 4),  # row 7, col 22
    (7, 21, 4),  # row 8, col 22
    (7, 22, 2),  # row 8, col 23
    (8, 20, 3),  # row 9, col 21
    (8, 22, 2)   # row 9, col 23
]

output = [[0]*26 for _ in range(16)]

# Create 1x1 squares at each scatter position with identity color
for r, c, val in test_scatters:
    output[r][c] = val

print("1x1 squares:")
for row in output:
    print(' '.join(str(x) for x in row))

# Try smaller rectangles (2x2 based on Demo 1 pattern)
output2 = [[0]*26 for _ in range(16)]
for r, c, val in test_scatters:
    for dr in range(2):
        for dc in range(2):
            if 0 <= r+dr < 16 and 0 <= c+dc < 26:
                output2[r+dr][c+dc] = val

print("\n2x2 rectangles:")
for row in output2:
    print(' '.join(str(x) for x in row))

